const queries = [
  'Java Developer fresher India',
  'Spring Boot Developer 0-2 years India',
  'Associate Software Engineer India',
  'Java Backend Developer junior India',
  'Java Spring Boot React Hyderabad',
  'Java Developer Bangalore 0-2 years'
];

return queries.map(q => ({ json: { query: q, timestamp: new Date().toISOString() } }));

// Aggregate results from all incoming source branches
const allItems = [];

// 1. Arbeitnow items
try {
  const arbeitItems = $items('Fetch Arbeitnow API');
  if (arbeitItems && arbeitItems.length > 0) {
    const data = arbeitItems[0].json.data || [];
    for (const j of data) {
      allItems.push({
        source: 'Arbeitnow',
        company: j.company_name,
        title: j.title,
        location: j.location || 'Remote',
        workMode: j.remote ? 'Remote' : 'On-site',
        description: j.description || '',
        skills: j.tags || [],
        publishedAt: j.created_at ? new Date(j.created_at * 1000).toISOString() : new Date().toISOString(),
        applicationUrl: j.url,
        companyCareersUrl: '',
        salary: 'Not Disclosed',
        jobReferenceId: j.slug
      });
    }
  }
} catch (e) {}

// 2. Remotive items
try {
  const remotiveItems = $items('Fetch Remotive API');
  if (remotiveItems && remotiveItems.length > 0) {
    const data = remotiveItems[0].json.jobs || [];
    for (const j of data) {
      const loc = (j.candidate_required_location || '').toLowerCase();
      if (loc.includes('india') || loc.includes('worldwide') || loc.includes('anywhere') || !loc) {
        allItems.push({
          source: 'Remotive',
          company: j.company_name,
          title: j.title,
          location: j.candidate_required_location || 'Remote (India / Worldwide)',
          workMode: 'Remote',
          description: j.description || '',
          skills: j.tags || [],
          publishedAt: j.publication_date ? new Date(j.publication_date).toISOString() : new Date().toISOString(),
          applicationUrl: j.url,
          companyCareersUrl: j.company_logo_url || '',
          salary: j.salary || 'Not Disclosed',
          jobReferenceId: String(j.id)
        });
      }
    }
  }
} catch (e) {}

return allItems.map(item => ({ json: item }));

const crypto = require('crypto');
const now = new Date();
const results = [];

for (const item of $input.all()) {
  const raw = item.json;

  // 1. Text sanitization
  const cleanText = (str) => (str || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
  const company = cleanText(raw.company || 'Confidential');
  const title = cleanText(raw.title || 'Software Developer');
  const location = cleanText(raw.location || 'India');
  const description = cleanText(raw.description || '');
  const applicationUrl = raw.applicationUrl || raw.url || '';

  // 2. Freshness calculation (Deterministic in code)
  let publishedAt = raw.publishedAt ? new Date(raw.publishedAt) : null;
  let freshnessVerified = Boolean(publishedAt && !isNaN(publishedAt.getTime()));
  let jobAgeHours = null;
  let freshnessScore = 0;
  let freshnessTier = 'UNVERIFIED';
  let freshnessLabel = 'Unknown';

  if (freshnessVerified) {
    const diffMs = Math.max(0, now.getTime() - publishedAt.getTime());
    jobAgeHours = parseFloat((diffMs / (1000 * 60 * 60)).toFixed(2));

    // 40-hour rule check
    if (jobAgeHours > 40.0) {
      continue; // REJECT STALE JOBS (> 40 Hours)
    }

    if (jobAgeHours <= 1.0) { freshnessScore = 100; freshnessTier = 'URGENT_0_1H'; freshnessLabel = 'Urgent (< 1h ago)'; }
    else if (jobAgeHours <= 3.0) { freshnessScore = 95; freshnessTier = 'PRIORITY_1_3H'; freshnessLabel = 'Posted 1-3h ago'; }
    else if (jobAgeHours <= 6.0) { freshnessScore = 90; freshnessTier = 'PRIORITY_3_6H'; freshnessLabel = 'Posted 3-6h ago'; }
    else if (jobAgeHours <= 12.0) { freshnessScore = 85; freshnessTier = 'PRIORITY_6_12H'; freshnessLabel = 'Posted 6-12h ago'; }
    else if (jobAgeHours <= 24.0) { freshnessScore = 75; freshnessTier = 'PRIORITY_12_24H'; freshnessLabel = 'Posted Today (< 24h)'; }
    else { freshnessScore = 60; freshnessTier = 'PRIORITY_24_40H'; freshnessLabel = 'Posted 24-40h ago'; }
  } else {
    // Drop unverified publication dates to preserve freshness integrity
    continue;
  }

  // 3. SHA-256 Fingerprint generation
  const normComp = company.toLowerCase().replace(/[^a-z0-9\s]/g, '').trim();
  const normTitle = title.toLowerCase().replace(/[^a-z0-9\s]/g, '').trim();
  const refId = String(raw.jobReferenceId || '').trim().toLowerCase();
  const cleanUrl = applicationUrl.split('?')[0].trim().toLowerCase();

  const canonicalString = (refId && refId.length > 2)
    ? `company:${normComp}|title:${normTitle}|ref:${refId}`
    : `company:${normComp}|title:${normTitle}|url:${cleanUrl}`;

  const jobFingerprint = crypto.createHash('sha256').update(canonicalString).digest('hex');
  const jobId = 'job_' + jobFingerprint.substring(0, 16);

  results.push({
    json: {
      jobId,
      jobFingerprint,
      source: raw.source || 'Aggregator',
      company,
      title,
      location,
      workMode: raw.workMode || 'On-site',
      employmentType: raw.employmentType || 'Full-time',
      description,
      skills: raw.skills || [],
      publishedAt: publishedAt.toISOString(),
      discoveredAt: now.toISOString(),
      jobAgeHours,
      freshnessScore,
      freshnessTier,
      freshnessLabel,
      freshnessVerified: true,
      applicationUrl,
      companyCareersUrl: raw.companyCareersUrl || '',
      salary: raw.salary || 'Not Disclosed',
      jobReferenceId: raw.jobReferenceId || ''
    }
  });
}

return results;

const SENIORITY_BLACKLIST = ['senior', 'sr.', 'sr ', 'lead', 'principal', 'staff engineer', 'architect', 'engineering manager', 'manager', 'director', 'vp', 'tech lead'];
const NON_DEV_BLACKLIST = ['bpo', 'call center', 'customer support', 'sales executive', 'marketing', 'hr executive', 'accountant', 'manual tester', 'data entry', 'desktop support', 'network engineer', 'mechanical', 'civil'];

const passedItems = [];

for (const item of $input.all()) {
  const job = item.json;
  const titleLower = job.title.toLowerCase();
  const descLower = job.description.toLowerCase();

  // Check seniority in title
  const isSenior = SENIORITY_BLACKLIST.some(term => new RegExp(`\\b${term.replace('.', '\\.')}\\b`, 'i').test(titleLower));
  if (isSenior) continue;

  // Check non-dev roles
  const isNonDev = NON_DEV_BLACKLIST.some(term => new RegExp(`\\b${term}\\b`, 'i').test(titleLower));
  if (isNonDev) continue;

  // Check explicit 3+ years experience requirement in text
  const expMatch = `${titleLower} ${descLower}`.match(/(?:minimum|requires?|mandatory|at least)\s+(\d+)\+?\s*years?/i);
  if (expMatch && parseInt(expMatch[1], 10) >= 3) continue;

  // Must have application URL
  if (!job.applicationUrl || job.applicationUrl.length < 5) continue;

  passedItems.push(item);
}

return passedItems;

