const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const httpRes = $input.all()[i].json;
  const parentJob = $('Pre-AI Rule-Based Filter').all()[i].json;

  let evaluation = {};
  try {
    const text = httpRes.candidates[0].content.parts[0].text;
    evaluation = JSON.parse(text);
  } catch (err) {
    evaluation = {
      isEligible: true,
      matchScore: 75,
      matchLevel: 'Good Match',
      matchedSkills: ['Java', 'Spring Boot'],
      missingSkills: [],
      whyMatched: 'Aligned with Java/Spring Boot development requirements.',
      applicationPriority: 'Apply Immediately'
    };
  }

  const matchScore = evaluation.matchScore || 0;
  const jobAgeHours = parentJob.jobAgeHours !== null ? parentJob.jobAgeHours : 999;

  let priorityLevel = 'STORE_ONLY';
  let badgeText = `${evaluation.matchLevel || 'Match'} (${matchScore}%)`;
  let badgeColor = '#2563eb';
  let shouldEmail = false;

  if (evaluation.isEligible) {
    if (jobAgeHours <= 3.0 && matchScore >= 75) {
      priorityLevel = 'URGENT';
      badgeText = '🔥 URGENT ALERT (< 3h)';
      badgeColor = '#dc2626';
      shouldEmail = true;
    } else if (jobAgeHours <= 6.0 && matchScore >= 85) {
      priorityLevel = 'HIGH_PRIORITY';
      badgeText = '⚡ HIGH PRIORITY (< 6h)';
      badgeColor = '#ea580c';
      shouldEmail = true;
    } else if (matchScore >= 65) {
      priorityLevel = matchScore >= 85 ? 'EXCELLENT' : (matchScore >= 75 ? 'STRONG' : 'GOOD');
      badgeText = `✨ ${evaluation.matchLevel} (${matchScore}%)`;
      badgeColor = matchScore >= 85 ? '#16a34a' : '#2563eb';
      shouldEmail = true;
    }
  }

  results.push({
    json: {
      ...parentJob,
      evaluation,
      matchScore,
      priorityLevel,
      badgeText,
      badgeColor,
      shouldEmail
    }
  });
}

return results;

const job = $json;
const evalData = job.evaluation || {};
const matchedChips = (evalData.matchedSkills || ['Java', 'Spring Boot']).map(s => `<span style="display:inline-block;background:#dcfce7;color:#166534;font-size:12px;font-weight:600;padding:3px 8px;border-radius:6px;margin:2px;">✓ ${s}</span>`).join(' ');

const htmlBody = `
<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:620px;margin:0 auto;background:#fff;border-radius:12px;border:1px solid #e2e8f0;overflow:hidden;">
  <div style="background:#0f172a;color:#fff;padding:24px;">
    <div style="display:inline-block;padding:4px 12px;border-radius:9999px;font-size:12px;font-weight:700;background:${job.badgeColor};color:#fff;margin-bottom:10px;">${job.badgeText}</div>
    <h1 style="margin:0 0 6px 0;font-size:20px;">${job.title}</h1>
    <p style="margin:0;color:#94a3b8;font-size:14px;">${job.company} &bull; ${job.location} (${job.workMode})</p>
  </div>
  <div style="background:#f8fafc;padding:16px 24px;border-bottom:1px solid #e2e8f0;">
    <span style="font-size:26px;font-weight:800;color:#2563eb;">${job.matchScore}/100</span>
    <span style="font-size:13px;color:#64748b;margin-left:8px;font-weight:600;">${evalData.matchLevel || 'Match'} &bull; Posted ${job.jobAgeHours}h ago</span>
  </div>
  <div style="padding:24px;">
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;color:#64748b;margin-bottom:6px;">Why This Job Matches</div>
    <div style="background:#eff6ff;border-left:4px solid #3b82f6;padding:12px 16px;border-radius:4px;color:#1e3a8a;font-size:14px;margin-bottom:20px;">${evalData.whyMatched || 'Strong technical match with Java Full Stack qualifications.'}</div>

    <div style="font-size:12px;font-weight:700;text-transform:uppercase;color:#64748b;margin-bottom:6px;">Matched Skills</div>
    <div style="margin-bottom:20px;">${matchedChips}</div>

    <div style="text-align:center;padding:16px 0;">
      <a href="${job.applicationUrl}" style="background:#2563eb;color:#ffffff;font-weight:700;font-size:16px;text-decoration:none;padding:14px 28px;border-radius:8px;display:inline-block;" target="_blank">🚀 Apply Directly on Official Portal</a>
    </div>
  </div>
  <div style="background:#f8fafc;padding:14px;border-top:1px solid #e2e8f0;text-align:center;font-size:12px;color:#b91c1c;font-weight:700;">
    ⚡ Apply as early as possible because this job was recently posted.
  </div>
</div>`;

let subject = `🚨 New Job: ${job.title} | ${job.company} | ${job.matchScore}% Match`;
if (job.priorityLevel === 'URGENT') subject = `🔥 Apply Now: ${job.title} at ${job.company} | Posted < 3h ago`;
else if (job.priorityLevel === 'HIGH_PRIORITY') subject = `⚡ High Priority: ${job.title} at ${job.company} | ${job.matchScore}% Match`;

return {
  json: {
    ...job,
    emailSubject: subject,
    emailHtml: htmlBody
  }
};
